  dark += gauss2(d, 45.0, -30.0, 12.0) * 0.8;    // Mare Acidalium
  dark += gauss2(d, -15.0, 105.0, 15.0) * 0.7;   // Mare Tyrrhenum
  dark += gauss2(d, -22.0, 145.0, 16.0) * 0.75;  // Mare Cimmerium
  dark += gauss2(d, -30.0, -155.0, 15.0) * 0.7;  // Mare Sirenum
  dark += gauss2(d, -28.0, -90.0, 7.0) * 0.6;    // Solis Lacus
  dark += gauss2(d, 48.0, 110.0, 16.0) * 0.45;   // Utopia
