const THREE = window.THREE;

const v = new THREE.Vector3();

/** DOM labels placed over the canvas, decluttered by priority. Also provides screen-space picking. */
class Labels {
  constructor(container, onPick) {
    this.container = container;
    this.onPick = onPick;
    this.pool = new Map();
    this.screen = [];
  }

  el(body) {
    let e = this.pool.get(body);
    if (!e) {
      e = document.createElement('div');
      e.className = `label ${body.type}`;
      e.textContent = body.name;
      e.addEventListener('click', (ev) => { ev.stopPropagation(); this.onPick(body, false); });
      e.addEventListener('dblclick', (ev) => { ev.stopPropagation(); this.onPick(body, true); });
      this.container.appendChild(e);
      this.pool.set(body, e);
      e._shown = false;
    }
    return e;
  }

  /**
   * candidates: [{ body, priority, rel:[x,y,z] (camera-relative km), offsetPx, label:boolean }]
   * Records screen positions of every candidate (for picking) and shows labels that do not overlap.
   */
  update(camera, width, height, candidates, focus) {
    this.screen.length = 0;
    const placed = [];
    const fwd = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    candidates.sort((a, b) => b.priority - a.priority);
    const used = new Set();
    for (const c of candidates) {
      v.set(c.rel[0], c.rel[1], c.rel[2]);
      if (v.dot(fwd) <= 0) continue;
      v.project(camera);
      if (v.x < -1.1 || v.x > 1.1 || v.y < -1.1 || v.y > 1.1) continue;
      const x = (v.x + 1) * 0.5 * width;
      const y = (1 - v.y) * 0.5 * height;
      this.screen.push({ body: c.body, x, y, r: Math.max(c.offsetPx, 6), priority: c.priority });
      if (!c.label) continue;
      const w = c.body.name.length * 6.6 + 10;
      const lx = x + Math.max(c.offsetPx, 3) + 3;
      const ly = y - 8;
      let overlap = false;
      for (const p of placed) {
        if (lx < p[2] && lx + w > p[0] && ly < p[3] && ly + 16 > p[1]) { overlap = true; break; }
      }
      if (overlap || placed.length > 160) continue;
      placed.push([lx, ly, lx + w, ly + 16]);
      const e = this.el(c.body);
      e.style.transform = `translate(${lx.toFixed(1)}px, ${ly.toFixed(1)}px)`;
      e.classList.toggle('focus', c.body === focus);
      if (!e._shown) { e.style.display = ''; e._shown = true; }
      used.add(c.body);
    }
    for (const [b, e] of this.pool) {
      if (!used.has(b) && e._shown) { e.style.display = 'none'; e._shown = false; }
    }
  }

  forget(body) {
    const e = this.pool.get(body);
    if (e) { e.remove(); this.pool.delete(body); }
  }

  /** Nearest pickable body to a screen point (within tolerance), preferring higher priority. */
  pick(x, y, tol = 14) {
    let best = null, bestScore = Infinity;
    for (const s of this.screen) {
      const d = Math.hypot(s.x - x, s.y - y);
      if (d > Math.max(tol, s.r + 4)) continue;
      const score = d - s.priority * 0.5;
      if (score < bestScore) { bestScore = score; best = s.body; }
    }
    return best;
  }
}

